@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap');

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --background: 222 47% 5%;
    --foreground: 210 40% 92%;
    --card: 222 40% 8%;
    --card-foreground: 210 40% 92%;
    --popover: 222 40% 8%;
    --popover-foreground: 210 40% 92%;
    --primary: 199 89% 48%;
    --primary-foreground: 222 47% 5%;
    --secondary: 222 35% 14%;
    --secondary-foreground: 210 40% 80%;
    --muted: 222 35% 12%;
    --muted-foreground: 210 20% 50%;
    --accent: 160 84% 39%;
    --accent-foreground: 222 47% 5%;
    --destructive: 0 84% 55%;
    --destructive-foreground: 0 0% 98%;
    --border: 222 30% 15%;
    --input: 222 30% 13%;
    --ring: 199 89% 48%;
    --radius: 0.5rem;

    /* OpsGrid custom tokens */
    --neon-blue: 199 89% 48%;
    --neon-green: 160 84% 39%;
    --neon-amber: 38 92% 50%;
    --neon-red: 0 84% 55%;
    --neon-purple: 270 76% 62%;
    --panel-bg: 222 40% 8%;
    --panel-border: 222 30% 15%;
    --grid-line: 222 30% 12%;

    --sidebar-background: 222 47% 4%;
    --sidebar-foreground: 210 40% 80%;
    --sidebar-primary: 199 89% 48%;
    --sidebar-primary-foreground: 222 47% 5%;
    --sidebar-accent: 222 35% 12%;
    --sidebar-accent-foreground: 210 40% 80%;
    --sidebar-border: 222 30% 12%;
    --sidebar-ring: 199 89% 48%;

    --chart-1: 199 89% 48%;
    --chart-2: 160 84% 39%;
    --chart-3: 38 92% 50%;
    --chart-4: 270 76% 62%;
    --chart-5: 0 84% 55%;
  }
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }

  body {
    @apply bg-background text-foreground font-inter;
    font-family: 'Inter', sans-serif;
  }

  code, pre, .mono {
    font-family: 'JetBrains Mono', monospace;
  }
}

@layer utilities {
  .neon-border-blue {
    border-color: hsl(var(--neon-blue) / 0.4);
    box-shadow: 0 0 12px hsl(var(--neon-blue) / 0.15), inset 0 0 12px hsl(var(--neon-blue) / 0.05);
  }
  .neon-border-green {
    border-color: hsl(var(--neon-green) / 0.4);
    box-shadow: 0 0 12px hsl(var(--neon-green) / 0.15), inset 0 0 12px hsl(var(--neon-green) / 0.05);
  }
  .neon-border-amber {
    border-color: hsl(var(--neon-amber) / 0.4);
    box-shadow: 0 0 12px hsl(var(--neon-amber) / 0.15);
  }
  .neon-border-red {
    border-color: hsl(var(--neon-red) / 0.4);
    box-shadow: 0 0 12px hsl(var(--neon-red) / 0.15);
  }
  .neon-text-blue { color: hsl(var(--neon-blue)); text-shadow: 0 0 8px hsl(var(--neon-blue) / 0.6); }
  .neon-text-green { color: hsl(var(--neon-green)); text-shadow: 0 0 8px hsl(var(--neon-green) / 0.6); }
  .neon-text-amber { color: hsl(var(--neon-amber)); text-shadow: 0 0 8px hsl(var(--neon-amber) / 0.6); }
  .neon-text-red { color: hsl(var(--neon-red)); text-shadow: 0 0 8px hsl(var(--neon-red) / 0.6); }

  .grid-bg {
    background-image:
      linear-gradient(hsl(var(--grid-line)) 1px, transparent 1px),
      linear-gradient(90deg, hsl(var(--grid-line)) 1px, transparent 1px);
    background-size: 40px 40px;
  }

  .panel {
    @apply bg-card border border-border rounded-lg;
  }

  .status-pulse-green {
    animation: pulse-green 2s infinite;
  }
  .status-pulse-red {
    animation: pulse-red 2s infinite;
  }
  .status-pulse-amber {
    animation: pulse-amber 2s infinite;
  }

  @keyframes pulse-green {
    0%, 100% { box-shadow: 0 0 4px hsl(160 84% 39% / 0.8); }
    50% { box-shadow: 0 0 12px hsl(160 84% 39% / 1); }
  }
  @keyframes pulse-red {
    0%, 100% { box-shadow: 0 0 4px hsl(0 84% 55% / 0.8); }
    50% { box-shadow: 0 0 12px hsl(0 84% 55% / 1); }
  }
  @keyframes pulse-amber {
    0%, 100% { box-shadow: 0 0 4px hsl(38 92% 50% / 0.8); }
    50% { box-shadow: 0 0 12px hsl(38 92% 50% / 1); }
  }

  .scrollbar-thin::-webkit-scrollbar { width: 4px; height: 4px; }
  .scrollbar-thin::-webkit-scrollbar-track { background: hsl(var(--muted)); }
  .scrollbar-thin::-webkit-scrollbar-thumb { background: hsl(var(--border)); border-radius: 2px; }
  .scrollbar-thin::-webkit-scrollbar-thumb:hover { background: hsl(var(--muted-foreground)); }
}

