import { useState, useEffect } from 'react';
import { Monitor, Cpu, HardDrive, Wifi, MemoryStick, RefreshCw, AlertCircle } from 'lucide-react';

function GaugeBar({ value, color }) {
  return (
    <div className="w-full h-1.5 bg-muted rounded-full overflow-hidden">
      <div
        className={`h-full rounded-full transition-all duration-500 ${color}`}
        style={{ width: `${Math.min(100, value)}%` }}
      />
    </div>
  );
}

function MetricRow({ label, value, unit, barValue, color }) {
  return (
    <div className="space-y-0.5">
      <div className="flex items-center justify-between text-xs font-mono">
        <span className="text-muted-foreground">{label}</span>
        <span className={color}>{value}<span className="text-muted-foreground ml-0.5">{unit}</span></span>
      </div>
      {barValue !== undefined && <GaugeBar value={barValue} color={color === 'text-neon-red' ? 'bg-neon-red' : color === 'text-neon-amber' ? 'bg-neon-amber' : 'bg-neon-green'} />}
    </div>
  );
}

function formatBytes(bytes) {
  if (bytes < 1024) return `${bytes} B/s`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB/s`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB/s`;
}

export default function ComputerMetricsWidget({ computer }) {
  const [data, setData] = useState(null);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);
  const [lastFetch, setLastFetch] = useState(null);

  const fetchMetrics = async () => {
    if (!computer) return;
    setLoading(true);
    setError(null);
    try {
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), 5000);
      const res = await fetch(`http://${computer.ip_address}:${computer.port}/system-report`, { signal: controller.signal });
      clearTimeout(timeout);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const json = await res.json();
      setData(json);
      setLastFetch(new Date());
    } catch (e) {
      setError(e.name === 'AbortError' ? 'Connection timed out' : 'Unable to reach computer');
    }
    setLoading(false);
  };

  useEffect(() => {
    if (!computer) return;
    fetchMetrics();
    const interval = setInterval(fetchMetrics, 10000);
    return () => clearInterval(interval);
  }, [computer?.id]);

  if (!computer) {
    return (
      <div className="h-full flex flex-col items-center justify-center text-center p-4">
        <Monitor className="w-8 h-8 text-muted-foreground mb-2" />
        <p className="text-xs font-mono text-muted-foreground">No computer selected</p>
        <p className="text-xs font-mono text-muted-foreground/60">Use the switcher above to select or add a computer</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="h-full flex flex-col items-center justify-center text-center p-4">
        <AlertCircle className="w-6 h-6 text-neon-red mb-2" />
        <p className="text-xs font-mono text-neon-red">{error}</p>
        <p className="text-xs font-mono text-muted-foreground mt-1">{computer.ip_address}:{computer.port}</p>
        <button onClick={fetchMetrics} className="mt-3 flex items-center gap-1 text-xs font-mono text-neon-blue hover:underline">
          <RefreshCw className="w-3 h-3" /> Retry
        </button>
      </div>
    );
  }

  if (loading && !data) {
    return (
      <div className="h-full flex items-center justify-center">
        <div className="text-xs font-mono text-muted-foreground animate-pulse">CONNECTING TO {computer.name.toUpperCase()}...</div>
      </div>
    );
  }

  if (!data) return null;

  const cpuColor = data.cpu.usage_percent > 80 ? 'text-neon-red' : data.cpu.usage_percent > 60 ? 'text-neon-amber' : 'text-neon-green';
  const memColor = data.memory.usage_percent > 85 ? 'text-neon-red' : data.memory.usage_percent > 70 ? 'text-neon-amber' : 'text-neon-green';
  const storColor = data.storage.usage_percent > 90 ? 'text-neon-red' : data.storage.usage_percent > 75 ? 'text-neon-amber' : 'text-neon-green';

  return (
    <div className="h-full flex flex-col gap-2">
      <div className="flex items-center justify-between flex-shrink-0">
        <div className="flex items-center gap-2">
          <Monitor className="w-3.5 h-3.5 text-neon-blue" />
          <span className="text-xs font-mono font-semibold text-foreground">{data.computer_name || computer.name}</span>
        </div>
        <div className="flex items-center gap-2">
          {loading && <div className="w-1.5 h-1.5 rounded-full bg-neon-blue animate-pulse" />}
          {lastFetch && <span className="text-xs font-mono text-muted-foreground/60">{lastFetch.toLocaleTimeString('en-US', { hour12: false })}</span>}
        </div>
      </div>

      <div className="flex-1 grid grid-cols-2 gap-3">
        {/* CPU */}
        <div className="p-2.5 rounded border border-border bg-muted/10 space-y-2">
          <div className="flex items-center gap-1.5">
            <Cpu className="w-3 h-3 text-neon-blue" />
            <span className="text-xs font-mono text-muted-foreground uppercase tracking-wider">CPU</span>
          </div>
          <MetricRow label="Usage" value={data.cpu.usage_percent.toFixed(1)} unit="%" barValue={data.cpu.usage_percent} color={cpuColor} />
          <MetricRow label="Cores" value={data.cpu.logical_cores} unit="" color="text-foreground" />
        </div>

        {/* Memory */}
        <div className="p-2.5 rounded border border-border bg-muted/10 space-y-2">
          <div className="flex items-center gap-1.5">
            <MemoryStick className="w-3 h-3 text-neon-purple" />
            <span className="text-xs font-mono text-muted-foreground uppercase tracking-wider">Memory</span>
          </div>
          <MetricRow label="Usage" value={data.memory.usage_percent.toFixed(1)} unit="%" barValue={data.memory.usage_percent} color={memColor} />
          <MetricRow label="Used" value={data.memory.used_gb} unit=" GB" color="text-foreground" />
          <MetricRow label="Total" value={data.memory.total_gb} unit=" GB" color="text-muted-foreground" />
        </div>

        {/* Storage */}
        <div className="p-2.5 rounded border border-border bg-muted/10 space-y-2">
          <div className="flex items-center gap-1.5">
            <HardDrive className="w-3 h-3 text-neon-amber" />
            <span className="text-xs font-mono text-muted-foreground uppercase tracking-wider">Storage</span>
          </div>
          <MetricRow label="Usage" value={data.storage.usage_percent.toFixed(1)} unit="%" barValue={data.storage.usage_percent} color={storColor} />
          <MetricRow label="Free" value={data.storage.free_gb} unit=" GB" color="text-foreground" />
          <MetricRow label="Total" value={data.storage.total_gb} unit=" GB" color="text-muted-foreground" />
        </div>

        {/* Network */}
        <div className="p-2.5 rounded border border-border bg-muted/10 space-y-2">
          <div className="flex items-center gap-1.5">
            <Wifi className="w-3 h-3 text-neon-green" />
            <span className="text-xs font-mono text-muted-foreground uppercase tracking-wider">Network</span>
          </div>
          <MetricRow label="↑ Upload" value={formatBytes(data.network.upload_speed_Bps)} unit="" color="text-neon-blue" />
          <MetricRow label="↓ Download" value={formatBytes(data.network.download_speed_Bps)} unit="" color="text-neon-green" />
        </div>
      </div>
    </div>
  );
}

src/components/computers/ComputerSetupWi:
import { useState } from 'react';
import { base44 } from '@/api/base44Client';
import { X, Monitor, Cpu, MemoryStick, HardDrive, Zap, CheckCircle2, Loader2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';

const COMPONENTS = [
  { key: 'has_cpu', label: 'CPU', icon: Cpu, borderOn: 'border-neon-blue/50', bgOn: 'bg-neon-blue/10', textOn: 'text-neon-blue', description: 'Simulate CPU load & usage' },
  { key: 'has_ram', label: 'RAM', icon: MemoryStick, borderOn: 'border-neon-green/50', bgOn: 'bg-neon-green/10', textOn: 'text-neon-green', description: 'Simulate memory pressure' },
  { key: 'has_storage', label: 'STORAGE', icon: HardDrive, borderOn: 'border-neon-amber/50', bgOn: 'bg-neon-amber/10', textOn: 'text-neon-amber', description: 'Simulate disk I/O & usage' },
  { key: 'has_gpu', label: 'GPU', icon: Zap, borderOn: 'border-neon-purple/50', bgOn: 'bg-neon-purple/10', textOn: 'text-neon-purple', description: 'Simulate GPU compute load' },
];

export default function ComputerSetupWizard({ onClose, onSaved, editComputer }) {
  const [name, setName] = useState(editComputer?.name || '');
  const [notes, setNotes] = useState(editComputer?.notes || '');
  const [components, setComponents] = useState({
    has_cpu: editComputer?.has_cpu ?? true,
    has_ram: editComputer?.has_ram ?? true,
    has_storage: editComputer?.has_storage ?? true,
    has_gpu: editComputer?.has_gpu ?? false,
  });
  const [saving, setSaving] = useState(false);
  const [nameError, setNameError] = useState('');

  const toggleComponent = (key) => {
    setComponents(prev => ({ ...prev, [key]: !prev[key] }));
  };

  const save = async () => {
    if (!name.trim()) {
      setNameError('Computer name is required');
      return;
    }
    setNameError('');
    setSaving(true);
    const payload = {
      name: name.trim(),
      notes: notes.trim(),
      status: 'idle',
      ...components,
      cpu_usage: 0,
      ram_usage: 0,
      storage_usage: 0,
      gpu_usage: 0,
    };
    if (editComputer) {
      await base44.entities.Computer.update(editComputer.id, payload);
    } else {
      await base44.entities.Computer.create(payload);
    }
    setSaving(false);
    onSaved();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-background/80 backdrop-blur-sm" onClick={onClose}>
      <div className="w-full max-w-md bg-card border border-border rounded-xl shadow-2xl overflow-hidden" onClick={e => e.stopPropagation()}>
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-border bg-card/60">
          <div className="flex items-center gap-3">
            <Monitor className="w-4 h-4 text-neon-blue" />
            <span className="text-sm font-mono font-semibold tracking-widest uppercase text-foreground">
              {editComputer ? 'Edit Computer' : 'Add Simulated Computer'}
            </span>
          </div>
          <button onClick={onClose} className="p-1 rounded hover:bg-muted/50 transition-colors">
            <X className="w-4 h-4 text-muted-foreground" />
          </button>
        </div>

        {/* Content */}
        <div className="p-6 space-y-5">
          {/* Name */}
          <div>
            <label className="text-xs font-mono text-muted-foreground mb-1.5 block">Computer Name</label>
            <Input
              value={name}
              onChange={e => { setName(e.target.value); setNameError(''); }}
              placeholder="e.g. Lab Node Alpha"
              className="bg-input border-border text-sm font-mono h-9"
            />
            {nameError && <p className="text-xs font-mono text-neon-red mt-1">{nameError}</p>}
          </div>

          {/* Components */}
          <div>
            <label className="text-xs font-mono text-muted-foreground mb-2 block uppercase tracking-wider">Simulated Hardware Components</label>
            <div className="grid grid-cols-2 gap-2">
              {COMPONENTS.map(({ key, label, icon: CompIcon, borderOn, bgOn, textOn, description }) => {
                const enabled = components[key];
                return (
                  <button
                    key={key}
                    onClick={() => toggleComponent(key)}
                    className={`flex flex-col items-start gap-2 p-3 rounded-lg border transition-all text-left ${
                      enabled ? `${borderOn} ${bgOn}` : 'border-border bg-muted/10 opacity-50'
                    }`}
                  >
                    <div className="flex items-center justify-between w-full">
                      <div className={`flex items-center gap-1.5 text-xs font-mono font-semibold ${enabled ? textOn : 'text-muted-foreground'}`}>
                        <CompIcon className="w-3.5 h-3.5" />
                        {label}
                      </div>
                      <div className={`w-8 h-4 rounded-full transition-all flex items-center px-0.5 ${enabled ? 'bg-muted-foreground/30' : 'bg-muted'}`}>
                        <div className={`w-3 h-3 rounded-full transition-transform ${enabled ? `translate-x-4 bg-white` : 'translate-x-0 bg-muted-foreground/50'}`} />
                      </div>
                    </div>
                    <span className="text-xs text-muted-foreground font-mono">{description}</span>
                  </button>
                );
              })}
            </div>
          </div>

          {/* Notes */}
          <div>
            <label className="text-xs font-mono text-muted-foreground mb-1.5 block">Notes (optional)</label>
            <Input
              value={notes}
              onChange={e => setNotes(e.target.value)}
              placeholder="e.g. Test environment node"
              className="bg-input border-border text-sm font-mono h-9"
            />
          </div>
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between px-6 py-4 border-t border-border bg-card/40">
          <Button variant="ghost" size="sm" onClick={onClose} className="text-xs font-mono text-muted-foreground">
            CANCEL
          </Button>
          <Button
            size="sm"
            onClick={save}
            disabled={saving}
            className="text-xs font-mono bg-neon-green/10 border border-neon-green/30 text-neon-green hover:bg-neon-green/20"
          >
            {saving ? <Loader2 className="w-3.5 h-3.5 mr-1 animate-spin" /> : <CheckCircle2 className="w-3.5 h-3.5 mr-1" />}
            {saving ? 'SAVING...' : 'SAVE COMPUTER'}
          </Button>
        </div>
      </div>
    </div>
  );
}

src/components/computers/ComputerSwitche:
import { useState, useEffect } from 'react';
import { base44 } from '@/api/base44Client';
import { Monitor, ChevronDown, Plus, Pencil, Trash2, RefreshCw, Wifi, WifiOff, Loader2 } from 'lucide-react';
import ComputerSetupWizard from './ComputerSetupWizard';

const statusConfig = {
  connected:  { label: 'Connected',  dot: 'bg-neon-green status-pulse-green', text: 'text-neon-green',       icon: '🟢' },
  connecting: { label: 'Connecting', dot: 'bg-neon-amber status-pulse-amber', text: 'text-neon-amber',       icon: '🟡' },
  online:     { label: 'Online',     dot: 'bg-neon-green status-pulse-green', text: 'text-neon-green',       icon: '🟢' },
  stressed:   { label: 'Stressed',   dot: 'bg-neon-red status-pulse-red',     text: 'text-neon-red',         icon: '🔴' },
  idle:       { label: 'Idle',       dot: 'bg-neon-blue',                     text: 'text-neon-blue',        icon: '🔵' },
  offline:    { label: 'Offline',    dot: 'bg-muted-foreground',              text: 'text-muted-foreground', icon: '⚫' },
  unknown:    { label: 'Unknown',    dot: 'bg-muted-foreground',              text: 'text-muted-foreground', icon: '⚪' },
};

export default function ComputerSwitcher({ activeId, onSelect, readOnly = false, selectOnly = false }) {
  const [computers, setComputers] = useState([]);
  const [open, setOpen] = useState(false);
  const [showWizard, setShowWizard] = useState(false);
  const [editComputer, setEditComputer] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(null);
  const [polling, setPolling] = useState({});

  const load = async () => {
    const data = await base44.entities.Computer.list('-created_date');
    setComputers(data);
    if (data.length > 0 && !activeId) {
      onSelect(data[0]);
    }
  };

  useEffect(() => {
    load();
  }, []);

  // Poll active computer status
  useEffect(() => {
    const active = computers.find(c => c.id === activeId);
    if (!active) return;

    const poll = async () => {
      setPolling(p => ({ ...p, [active.id]: true }));
      try {
        const controller = new AbortController();
        const timeout = setTimeout(() => controller.abort(), 4000);
        const res = await fetch(`http://${active.ip_address}:${active.port}/system-report`, { signal: controller.signal });
        clearTimeout(timeout);
        const newStatus = res.ok ? 'connected' : 'offline';
        if (active.status !== newStatus) {
          await base44.entities.Computer.update(active.id, { status: newStatus, last_seen: res.ok ? new Date().toISOString() : active.last_seen });
          load();
        }
      } catch {
        if (active.status !== 'offline') {
          await base44.entities.Computer.update(active.id, { status: 'offline' });
          load();
        }
      }
      setPolling(p => ({ ...p, [active.id]: false }));
    };

    poll();
    const interval = setInterval(poll, 15000);
    return () => clearInterval(interval);
  }, [activeId, computers.length]);

  const handleDelete = async (computer) => {
    await base44.entities.Computer.delete(computer.id);
    if (activeId === computer.id) onSelect(null);
    setConfirmDelete(null);
    load();
  };

  const active = computers.find(c => c.id === activeId);
  const activeCfg = statusConfig[active?.status || 'unknown'];

  return (
    <>
      <div className="relative">
        <button
          onClick={() => !readOnly && setOpen(p => !p)}
          className={`flex items-center gap-2 px-3 py-1.5 rounded-lg border border-border bg-card/60 text-xs font-mono ${readOnly ? 'cursor-default opacity-80' : 'hover:bg-muted/30 transition-colors'}`}
        >
          <Monitor className="w-3.5 h-3.5 text-neon-blue" />
          {active ? (
            <>
              <div className={`w-1.5 h-1.5 rounded-full ${activeCfg.dot}`} />
              <span className="text-foreground max-w-28 truncate">{active.name}</span>
            </>
          ) : (
            <span className="text-muted-foreground">Select Computer</span>
          )}
          {!readOnly && <ChevronDown className="w-3 h-3 text-muted-foreground" />}
        </button>

        {open && !readOnly && (
          <div className="absolute top-full left-0 mt-1 w-72 bg-card border border-border rounded-lg shadow-2xl z-50 overflow-hidden">
            <div className="px-3 py-2 border-b border-border flex items-center justify-between">
              <span className="text-xs font-mono text-muted-foreground uppercase tracking-widest">Computers</span>
              {!selectOnly && (
                <button
                  onClick={() => { setEditComputer(null); setShowWizard(true); setOpen(false); }}
                  className="flex items-center gap-1 text-xs font-mono text-neon-blue hover:text-neon-blue/80 transition-colors"
                >
                  <Plus className="w-3 h-3" /> Add
                </button>
              )}
            </div>

            {computers.length === 0 ? (
              <div className="p-4 text-center">
                <Monitor className="w-6 h-6 text-muted-foreground mx-auto mb-2" />
                <p className="text-xs font-mono text-muted-foreground">No computers configured</p>
                {!selectOnly && (
                  <button
                    onClick={() => { setEditComputer(null); setShowWizard(true); setOpen(false); }}
                    className="mt-2 text-xs font-mono text-neon-blue hover:underline"
                  >
                    + Setup first computer
                  </button>
                )}
              </div>
            ) : (
              <div className="max-h-60 overflow-auto scrollbar-thin">
                {computers.map(c => {
                  const cfg = statusConfig[c.status || 'unknown'];
                  return (
                    <div
                      key={c.id}
                      className={`flex items-center gap-2 px-3 py-2.5 hover:bg-muted/30 transition-colors cursor-pointer group ${
                        c.id === activeId ? 'bg-neon-blue/5 border-l-2 border-neon-blue' : ''
                      }`}
                      onClick={() => { onSelect(c); setOpen(false); }}
                    >
                      <div className={`w-1.5 h-1.5 rounded-full flex-shrink-0 ${cfg.dot}`} />
                      <div className="flex-1 min-w-0">
                        <div className="text-xs font-mono text-foreground truncate">{c.name}</div>
                        <div className="text-xs font-mono text-muted-foreground">{c.ip_address}:{c.port}</div>
                      </div>
                      {!selectOnly && (
                        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                          {polling[c.id] && <Loader2 className="w-3 h-3 text-muted-foreground animate-spin" />}
                          <button
                            onClick={e => { e.stopPropagation(); setEditComputer(c); setShowWizard(true); setOpen(false); }}
                            className="p-1 rounded hover:bg-muted/50"
                          >
                            <Pencil className="w-3 h-3 text-muted-foreground" />
                          </button>
                          <button
                            onClick={e => { e.stopPropagation(); setConfirmDelete(c); setOpen(false); }}
                            className="p-1 rounded hover:bg-neon-red/10"
                          >
                            <Trash2 className="w-3 h-3 text-neon-red" />
                          </button>
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            )}

            <div className="px-3 py-2 border-t border-border">
              <button onClick={() => { load(); }} className="flex items-center gap-1 text-xs font-mono text-muted-foreground hover:text-foreground transition-colors">
                <RefreshCw className="w-3 h-3" /> Refresh
              </button>
            </div>
          </div>
        )}

        {/* Click outside to close */}
        {open && <div className="fixed inset-0 z-40" onClick={() => setOpen(false)} />}
      </div>

      {/* Setup Wizard */}
      {showWizard && (
        <ComputerSetupWizard
          onClose={() => { setShowWizard(false); setEditComputer(null); }}
          onSaved={() => { setShowWizard(false); setEditComputer(null); load(); }}
          editComputer={editComputer}
        />
      )}

      {/* Delete confirmation */}
      {confirmDelete && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-background/80 backdrop-blur-sm">
          <div className="w-80 bg-card border border-border rounded-xl p-6 shadow-2xl">
            <div className="flex items-center gap-2 mb-3">
              <Trash2 className="w-4 h-4 text-neon-red" />
              <span className="text-sm font-mono font-semibold text-foreground">Remove Computer</span>
            </div>
            <p className="text-xs font-mono text-muted-foreground mb-4">
              Remove <span className="text-foreground font-semibold">{confirmDelete.name}</span>? This cannot be undone.
            </p>
            <div className="flex gap-2 justify-end">
              <button
                onClick={() => setConfirmDelete(null)}
                className="px-3 py-1.5 text-xs font-mono border border-border rounded hover:bg-muted/30 text-muted-foreground transition-colors"
              >
                CANCEL
              </button>
              <button
                onClick={() => handleDelete(confirmDelete)}
                className="px-3 py-1.5 text-xs font-mono border border-neon-red/30 bg-neon-red/10 text-neon-red rounded hover:bg-neon-red/20 transition-colors"
              >
                REMOVE
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

