import { useState, useEffect } from 'react';
import { AlertTriangle, CheckCircle, Clock, X } from 'lucide-react';
import { base44 } from '@/api/base44Client';
import { formatDistanceToNow } from 'date-fns';

const severityConfig = {
  low: { color: 'text-neon-blue', bg: 'bg-neon-blue/10', border: 'border-neon-blue/20', label: 'LOW' },
  medium: { color: 'text-neon-amber', bg: 'bg-neon-amber/10', border: 'border-neon-amber/20', label: 'MED' },
  critical: { color: 'text-neon-red', bg: 'bg-neon-red/10', border: 'border-neon-red/20', label: 'CRIT' },
};

export default function AlertFeedWidget() {
  const [alerts, setAlerts] = useState([]);

  useEffect(() => {
    base44.entities.Alert.list('-created_date', 8).then(setAlerts).catch(() => {});
    const unsub = base44.entities.Alert.subscribe(() => {
      base44.entities.Alert.list('-created_date', 8).then(setAlerts).catch(() => {});
    });
    return () => unsub();
  }, []);

  const acknowledge = async (id) => {
    await base44.entities.Alert.update(id, { status: 'acknowledged' });
  };

  return (
    <div className="h-full flex flex-col gap-3">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <AlertTriangle className="w-4 h-4 text-neon-amber" />
          <span className="text-xs font-mono uppercase tracking-widest text-muted-foreground">Alert Feed</span>
        </div>
        <span className="text-xs font-mono text-muted-foreground">{alerts.filter(a => a.status === 'active').length} active</span>
      </div>

      <div className="flex-1 overflow-y-auto space-y-1.5 scrollbar-thin pr-1">
        {alerts.length === 0 && (
          <div className="flex flex-col items-center justify-center h-24 text-muted-foreground">
            <CheckCircle className="w-6 h-6 mb-2 text-neon-green" />
            <span className="text-xs font-mono">ALL CLEAR</span>
          </div>
        )}
        {alerts.map(alert => {
          const cfg = severityConfig[alert.severity] || severityConfig.low;
          return (
            <div
              key={alert.id}
              className={`flex items-start gap-2 p-2 rounded border ${cfg.bg} ${cfg.border} ${
                alert.status !== 'active' ? 'opacity-50' : ''
              }`}
            >
              <span className={`text-xs font-mono font-bold flex-shrink-0 ${cfg.color} mt-0.5`}>
                {cfg.label}
              </span>
              <div className="flex-1 min-w-0">
                <p className="text-xs text-foreground/90 leading-relaxed truncate">{alert.message}</p>
                <div className="flex items-center gap-1 mt-0.5">
                  <Clock className="w-2.5 h-2.5 text-muted-foreground" />
                  <span className="text-xs text-muted-foreground font-mono">
                    {formatDistanceToNow(new Date(alert.created_date), { addSuffix: true })}
                  </span>
                </div>
              </div>
              {alert.status === 'active' && (
                <button
                  onClick={() => acknowledge(alert.id)}
                  className="flex-shrink-0 p-0.5 rounded hover:bg-white/10 transition-colors"
                  title="Acknowledge"
                >
                  <X className="w-3 h-3 text-muted-foreground" />
                </button>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

src/components/dashboard/AnalyticsProfil:
import { useState, useEffect, useRef } from 'react';
import { BarChart2, TrendingUp, TrendingDown, Minus } from 'lucide-react';
import { AreaChart, Area, BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid } from 'recharts';

function generateHourlyData() {
  return Array.from({ length: 24 }, (_, i) => ({
    hour: `${String(i).padStart(2, '0')}:00`,
    requests: Math.floor(3000 + Math.random() * 8000),
    errors: Math.floor(Math.random() * 200),
    latency: Math.floor(40 + Math.random() * 120),
  }));
}

const METRICS = [
  { key: 'requests', label: 'Requests/hr', color: '#0ea5e9', format: v => v.toLocaleString() },
  { key: 'errors',   label: 'Errors/hr',   color: '#ef4444', format: v => v.toLocaleString() },
  { key: 'latency',  label: 'Avg Latency', color: '#f59e0b', format: v => `${v}ms` },
];

function StatCard({ label, value, trend, color }) {
  const TrendIcon = trend > 0 ? TrendingUp : trend < 0 ? TrendingDown : Minus;
  return (
    <div className="p-3 rounded-lg border border-border bg-muted/10 flex flex-col gap-1">
      <span className="text-xs font-mono text-muted-foreground uppercase tracking-wider">{label}</span>
      <span className="text-xl font-mono font-bold" style={{ color }}>{value}</span>
      <TrendIcon className="w-3 h-3" style={{ color: trend > 0 ? '#22c55e' : trend < 0 ? '#ef4444' : '#64748b' }} />
    </div>
  );
}

export default function AnalyticsProfileWidget() {
  const [data, setData] = useState(generateHourlyData);
  const [activeMetric, setActiveMetric] = useState('requests');

  useEffect(() => {
    const id = setInterval(() => setData(generateHourlyData()), 10000);
    return () => clearInterval(id);
  }, []);

  const metric = METRICS.find(m => m.key === activeMetric);
  const latest = data[data.length - 1];
  const prev = data[data.length - 2];

  return (
    <div className="h-full flex flex-col gap-3">
      <div className="flex items-center gap-2">
        <BarChart2 className="w-4 h-4 text-neon-blue" />
        <span className="text-xs font-mono uppercase tracking-widest text-muted-foreground">Analytics — 24h Breakdown</span>
      </div>

      {/* Stat cards */}
      <div className="grid grid-cols-3 gap-2">
        {METRICS.map(m => (
          <StatCard
            key={m.key}
            label={m.label}
            value={m.format(latest[m.key])}
            trend={latest[m.key] - prev[m.key]}
            color={m.color}
          />
        ))}
      </div>

      {/* Metric tabs */}
      <div className="flex gap-1">
        {METRICS.map(m => (
          <button
            key={m.key}
            onClick={() => setActiveMetric(m.key)}
            className={`text-xs font-mono px-2 py-0.5 rounded border transition-colors ${activeMetric === m.key ? 'border-neon-blue/40 bg-neon-blue/10 text-neon-blue' : 'border-border text-muted-foreground hover:text-foreground'}`}
          >
            {m.label}
          </button>
        ))}
      </div>

      {/* Chart */}
      <div className="flex-1 min-h-0">
        <ResponsiveContainer width="100%" height="100%">
          <AreaChart data={data} margin={{ top: 4, right: 4, bottom: 0, left: -20 }}>
            <defs>
              <linearGradient id="aGrad" x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor={metric.color} stopOpacity={0.3} />
                <stop offset="95%" stopColor={metric.color} stopOpacity={0} />
              </linearGradient>
            </defs>
            <CartesianGrid strokeDasharray="3 3" stroke="hsl(222 30% 15%)" />
            <XAxis dataKey="hour" tick={{ fill: '#64748b', fontSize: 9 }} interval={3} />
            <YAxis tick={{ fill: '#64748b', fontSize: 9 }} />
            <Tooltip
              contentStyle={{ background: 'hsl(222 40% 8%)', border: '1px solid hsl(222 30% 15%)', borderRadius: 6, fontSize: 11, fontFamily: 'monospace' }}
              labelStyle={{ color: '#94a3b8' }}
              itemStyle={{ color: metric.color }}
            />
            <Area type="monotone" dataKey={activeMetric} stroke={metric.color} fill="url(#aGrad)" strokeWidth={1.5} dot={false} />
          </AreaChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

src/components/dashboard/AnalyticsWidget:
import { useState, useEffect } from 'react';
import { AreaChart, Area, XAxis, YAxis, Tooltip, ResponsiveContainer, BarChart, Bar } from 'recharts';
import { TrendingUp } from 'lucide-react';

function generateData(points = 20) {
  return Array.from({ length: points }, (_, i) => ({
    t: `${String(i).padStart(2, '0')}:00`,
    requests: Math.floor(Math.random() * 800 + 200),
    errors: Math.floor(Math.random() * 50),
    latency: Math.floor(Math.random() * 200 + 50),
  }));
}

const CustomTooltip = ({ active, payload, label }) => {
  if (!active || !payload?.length) return null;
  return (
    <div className="bg-card border border-border rounded p-2 text-xs font-mono">
      <p className="text-muted-foreground mb-1">{label}</p>
      {payload.map(p => (
        <p key={p.dataKey} style={{ color: p.color }}>{p.dataKey}: {p.value}</p>
      ))}
    </div>
  );
};

export default function AnalyticsWidget() {
  const [data, setData] = useState(generateData());
  const [view, setView] = useState('requests');

  useEffect(() => {
    const t = setInterval(() => {
      setData(prev => {
        const next = [...prev.slice(1), {
          t: new Date().toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: false }),
          requests: Math.floor(Math.random() * 800 + 200),
          errors: Math.floor(Math.random() * 50),
          latency: Math.floor(Math.random() * 200 + 50),
        }];
        return next;
      });
    }, 3000);
    return () => clearInterval(t);
  }, []);

  const views = [
    { key: 'requests', label: 'REQ/s', color: '#22d3ee' },
    { key: 'errors', label: 'ERRORS', color: '#f43f5e' },
    { key: 'latency', label: 'LATENCY', color: '#f59e0b' },
  ];

  const current = views.find(v => v.key === view);

  return (
    <div className="h-full flex flex-col gap-3">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <TrendingUp className="w-4 h-4 text-neon-blue" />
          <span className="text-xs font-mono uppercase tracking-widest text-muted-foreground">Live Analytics</span>
        </div>
        <div className="flex gap-1">
          {views.map(v => (
            <button
              key={v.key}
              onClick={() => setView(v.key)}
              className={`text-xs font-mono px-2 py-0.5 rounded transition-colors ${
                view === v.key ? 'bg-neon-blue/20 text-neon-blue border border-neon-blue/30' : 'text-muted-foreground hover:text-foreground'
              }`}
            >
              {v.label}
            </button>
          ))}
        </div>
      </div>

      <div className="flex-1 min-h-0">
        <ResponsiveContainer width="100%" height="100%">
          <AreaChart data={data} margin={{ top: 4, right: 4, bottom: 0, left: -20 }}>
            <defs>
              <linearGradient id="grad" x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor={current.color} stopOpacity={0.3} />
                <stop offset="95%" stopColor={current.color} stopOpacity={0} />
              </linearGradient>
            </defs>
            <XAxis dataKey="t" tick={{ fill: '#6b7280', fontSize: 9, fontFamily: 'JetBrains Mono' }} interval={4} />
            <YAxis tick={{ fill: '#6b7280', fontSize: 9, fontFamily: 'JetBrains Mono' }} />
            <Tooltip content={<CustomTooltip />} />
            <Area
              type="monotone"
              dataKey={view}
              stroke={current.color}
              strokeWidth={1.5}
              fill="url(#grad)"
              dot={false}
              isAnimationActive={false}
            />
          </AreaChart>
        </ResponsiveContainer>
      </div>

      {/* KPI row */}
      <div className="grid grid-cols-3 gap-2 pt-1 border-t border-border">
        <KPI label="AVG REQ" value="487/s" color="text-neon-blue" />
        <KPI label="ERROR RATE" value="2.4%" color="text-neon-amber" />
        <KPI label="P99 LAT" value="142ms" color="text-neon-green" />
      </div>
    </div>
  );
}

function KPI({ label, value, color }) {
  return (
    <div className="text-center">
      <div className="text-xs text-muted-foreground font-mono">{label}</div>
      <div className={`text-sm font-mono font-bold ${color}`}>{value}</div>
    </div>
  );
}

